package com.cosmicpve.combat.enchantment;
import static org.junit.jupiter.api.Assertions.*;import com.cosmicpve.combat.proc.ProcChance;import com.cosmicpve.equipment.enchantment.CosmicEnchantmentSpecs;import com.cosmicpve.equipment.enchantment.CosmicEnchantmentTier;import java.util.List;import org.junit.jupiter.api.Test;
class StormcallerBehaviorTest{@Test void metadataAndRandomPoolAreCanonical(){assertEquals(CosmicEnchantmentTier.ELITE,CosmicEnchantmentSpecs.STORMCALLER.tier());assertEquals("boots_or_chestplate",CosmicEnchantmentSpecs.STORMCALLER.equipmentApplicability());assertEquals(5,CosmicEnchantmentSpecs.STORMCALLER.maxLevel());assertTrue(CosmicEnchantmentSpecs.STORMCALLER.randomPoolEligible());assertTrue(CosmicEnchantmentSpecs.STORMCALLER.tier().extractableByBlackScroll());}@Test void aggregateChanceDamageAndDurationAreExact(){assertEquals(.01,StormcallerBehavior.chance(1));assertEquals(.05,StormcallerBehavior.chance(5));assertEquals(.05,StormcallerBehavior.chance(10));assertEquals(1.2,StormcallerBehavior.trueDamage(1),1e-12);assertEquals(3.0,StormcallerBehavior.trueDamage(10),1e-12);assertEquals(40,StormcallerBehavior.durationTicks(7));assertEquals(60,StormcallerBehavior.durationTicks(8));assertEquals(.06,ProcChance.calculate(.05,List.of(LuckBehavior.chanceMultiplier(20))),1e-12);}}
